-- ui Quick Time Event;  启动之后, 需要玩家疯狂点击屏幕来让进度条向右走; 当走到最右侧后, 判断玩家赢;


--- from: Assets/BundleResources/Prefabs/IdolLive3D_MainUI.prefab > name: Cell
---@class IdolLive3D_UIQTE                     
local IdolLive3D_UIQTE = Class('IdolLive3D_UIQTE')

-- 外部访问时使用:
-- ---@type IdolLive3D_UIQTE
-- local IdolLive3D_UIQTE = import('Game.IdolLive3D.IdolLive3D_UIQTE')



-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Mathf = CS.UnityEngine.Mathf
local Vector3 = CS.UnityEngine.Vector3
local CanvasGroup = CS.UnityEngine.CanvasGroup
local Time = CS.UnityEngine.Time
local Input = CS.UnityEngine.Input
local KeyCode = CS.UnityEngine.KeyCode
local Random = CS.UnityEngine.Random
local Screen = CS.UnityEngine.Screen

local Slider = CS.UnityEngine.UI.Slider 


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool


local DreamSpaceUtils = CS.DreamSpace.DreamSpaceUtils

local IdolLive3D_Utils = import('Game.IdolLive3D.IdolLive3D_Utils')

---@type IdolLive3D_States
local IdolLive3D_States = import('Game.IdolLive3D.IdolLive3D_States')
local PlayState = IdolLive3D_States.PlayState

local IdolLive3D_Input = import("Game.IdolLive3D.IdolLive3D_Input")

-- ========================================================


local headIconPath = "Arts/Icons/MainQuestHead/role_q_head_%d.png"


local animName_Enter  = "IdolLive3D_MainUI_Interaction_Enter"
local animName_Battle = "IdolLive3D_MainUI_Interaction_Battle"
local animName_Out    = "IdolLive3D_MainUI_Interaction_Out"
local animName_PlayerWin    = "IdolLive3D_MainUI_Interaction_PlayerWin"
local animName_RoleWin      = "IdolLive3D_MainUI_Interaction_RoleWin"




-- ========================================================



function IdolLive3D_UIQTE:__init( InteractionTF_, isInitShow_ )
    
    self.Interaction = InteractionTF_
    self:_Show(isInitShow_==true)
    
    ---
    self.ImgbgTips = self.Interaction:Find("Layout/ImgbgTips") -- 操作提示
    self.Left = self.Interaction:Find("Root/Left")
    self.Right = self.Interaction:Find("Root/Right")
    self.leftSlider  = KTool.GetComponent(self.Left.gameObject, typeof(Slider))
    self.rightSlider = KTool.GetComponent(self.Right.gameObject, typeof(Slider))

    self.Handle_L = self.Interaction:Find("Root/Handle_L")
    self.Handle_R = self.Interaction:Find("Root/Handle_R")
    self.imgIcon_player = self.Interaction:Find("Root/Handle_L/ImgIcon")
    self.imgIcon_idol   = self.Interaction:Find("Root/Handle_R/ImgIcon")
    self.Cursor         = self.Interaction:Find("Root/Cursor") -- 光标,  需要手动计算位置...

    ---
    self.CutTime        = self.Interaction:Find("CutTime") -- 倒计时
    self.CutTimeTxt     = self.CutTime:Find("ImgbgTips/TxtTime") -- 几秒

    self.playTipsTxt = self.Interaction:Find("Layout/ImgbgTips/TxtDesc") -- 屏幕下方文本提示, 如: "连续点击屏幕,想办法推到xxx"


    -- todo:  需要手动写 斯维蒂 提示语 ...

    self.LeftInitPos = self.Left.position
    self.RightInitPos = self.Right.position


    --- 倒计时数据:
    self._countDown = {
        startPointTime = Time.time, -- 倒计时功能启动瞬间的 时间;
        duration = 0, -- 倒计时总长度

        ---@return boolean
        IsNeedShow = function()
            local timeOffset = Time.time - self._countDown.startPointTime
            return      (self._countDown.duration >= 1) 
                    and (timeOffset > 0 and timeOffset < self._countDown.duration )
        end,

        ---@return integer
        GetIntNum = function()
            local timeOffset = self._countDown.duration - (Time.time - self._countDown.startPointTime)
            --print("num = " .. tostring(timeOffset))
            return checkInt(timeOffset)
        end,

        ---@return nil
        Update = function()
            local num = self._countDown.GetIntNum() 
            CfUtils.FillText( self.CutTimeTxt.gameObject, string.format("%ds", num) )
            KTool.SetActive( self.CutTime.gameObject, self._countDown.IsNeedShow() == true )
        end
    }

    self.UIFX_PushAside = self.Left:Find("Handle/UIFX_PushAside") -- 玩家开始操作后点亮, 然后不管它
    KTool.SetActive( self.UIFX_PushAside, false ) -- 默认关闭

    --- 设置调查官 头像:
    self:_SetHeadIcon( self.imgIcon_player, CfUtils.IsWoman() and 20003 or 20002 )

    -----
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
    self.events = CfUtils.EventsDecorated({
        [IdolLive3D_States.EventSuperTL_StartQTE]       = Bind(self, self.StartPlay),
        [IdolLive3D_States.EventSuperTL_EndQTE]         = Bind(self, self.EndPlay),
    })

    ---
    self.playState = PlayState.Before
    self.isSuccess = false -- 玩家是否在本次对抗中赢;
    self.playerTouchCount = 0 -- 在本次游戏中, 玩家触控屏幕次数

    ---
    self.isInit = true
end



-- 需手动调用 Delete()
function IdolLive3D_UIQTE:__delete()
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end

    IdolLive3D_Utils.StopCoroutine(self.co_1)
    self.co_1 = nil
    IdolLive3D_Utils.StopCoroutine(self.co_2)
    self.co_2 = nil
end



----------------------------------------------------------

function IdolLive3D_UIQTE:SelfUpdate( deltaTime_ )
    if self.isInit ~= true then 
        return
    end 
    if self.playState ~= PlayState.Playing then 
        return
    end 

    -- ====== 每一帧必须扣掉的值: =====
    local reduceVal = self.reduceSpeed * deltaTime_

    -- ======= 玩家点击帧, 涨的值: =======
    --local t = Mathf.Clamp01( KTool.Remap( 0.5, 1, 0, 1, Mathf.Clamp01(self.sliderVal) )) -- <=0.5 时为 min; 接近 1 时为 1;
    local t = Mathf.Clamp01(self.sliderVal) -- <=0.5 时为 min; 接近 1 时为 1;
    local growVal = Mathf.Lerp( self.maxGrowValOnceTouch, self.minGrowValOnceTouch, t )
    
    ---
    self.sliderVal = self.sliderVal - reduceVal

    local isSingleTouch = IdolLive3D_Input.IsSingleTouchUp()
    if isSingleTouch == true then 
        if self.playerTouchCount == 0  then
            KTool.SetActive( self.UIFX_PushAside, true )      
        end 
        self.playerTouchCount = self.playerTouchCount + 1
        --print( "red = " ..tostring(reduceVal) .. "; grow = " .. tostring(growVal) )
        self.sliderVal = self.sliderVal + reduceVal + growVal
    end 

    self.sliderVal = Mathf.Max( self.sliderVal, 0.0 )

    self:_SetSlider( self.sliderVal )

    --- 倒计时:
    self._countDown.Update()

    ---- 输赢判断:
    self.isSuccess = (self.sliderVal >= 0.5)

    -- =================== 玩家彻底赢 =======================
    if self.sliderVal >= 1.0 then 
        self.playState = PlayState.Finished
        KTool.SetActive( self.ImgbgTips, false ) -- 下方提示文字不需要了
        CfUtils.PlayAnimation( self.Interaction.gameObject, animName_Out, false )
    end 
end


--- ============================= 倒计时 =========================================


--- 启动倒计时:
---@param startPointTime_ number 倒计时开始时间点, 允许此点为: 曾经/现在/未来
---@param duration_ number
function IdolLive3D_UIQTE:StartCountDown( startPointTime_, duration_ )
    self._countDown.duration = Mathf.Max( checkNumber(duration_), 0 )
    self._countDown.startPointTime = checkNumber(startPointTime_)
    -- if self._countDown.IsNeedShow() == true then 
    --     self._countDown.Show( true )
    -- end 
end



--- ============================= 倒计时 =========================================

function IdolLive3D_UIQTE:_SetHeadIcon( tf_, roleId_ )
    local path = string.format(headIconPath, roleId_)
    CfUtils.FillImage(tf_, path )
end




---@param isShow_ boolean
function IdolLive3D_UIQTE:_Show( isShow_ )
    KTool.SetActive( self.Interaction.gameObject, isShow_ )
end



---@param sliderVal_ number @ [0.0,1.0] 0:最左,玩家输 1:最右,玩家赢
function IdolLive3D_UIQTE:_SetSlider( sliderVal_ )
    sliderVal_ = Mathf.Clamp( checkNumber(sliderVal_), 0.0, 1.0 )
    self.leftSlider.value = sliderVal_
    self.rightSlider.value = 1.0 - sliderVal_

    local cursorPos = Vector3.Lerp( self.Handle_L.position, self.Handle_R.position, sliderVal_ )
    self.Cursor.position = cursorPos
end



---@param roleId_ number @ int 比如 20002 
---@param initSliderVal_ number @ 如: 0.5
---@param reduceSpeed_ number @ 向左移动的速度 (自动恢复的速度)
---@param minGrowValOnceTouch_ number @ 
---@param maxGrowValOnceTouch_ number @ 
---@param countDownParams_ table @ 倒计时参数组
---@param playTipsTxt string @ 屏幕下方的游戏提示, 如: "连续点击屏幕,想办法推到xxx"; 调用者自己关心 文本翻译问题
function IdolLive3D_UIQTE:StartPlay( roleId_, initSliderVal_, reduceSpeed_, minGrowValOnceTouch_, maxGrowValOnceTouch_, countDownParams_, playTipsTxt_ )
    if self.isInit ~= true then 
        printError("调用时序有问题") 
        return
    end 

    self.sliderVal    = Mathf.Clamp01( checkNumber(initSliderVal_) )
    self.reduceSpeed  = Mathf.Clamp01( checkNumber(reduceSpeed_) )
    self.minGrowValOnceTouch = Mathf.Clamp01( checkNumber(minGrowValOnceTouch_) )
    self.maxGrowValOnceTouch = Mathf.Clamp01( checkNumber(maxGrowValOnceTouch_) )

    --- ======== 倒计时参数 ========
    if isTable(countDownParams_) then 
        self:StartCountDown( countDownParams_.startPointTime, countDownParams_.duration )
    end

    -- =====================
    self:_SetSlider( self.sliderVal )
    -- 设置 idol 头像:
    self:_SetHeadIcon( self.imgIcon_idol, checkInt(roleId_) )

    self:_Show(true)
    CfUtils.PlayAnimation( self.Interaction.gameObject, animName_Enter, false )
    
    KTool.SetActive( self.UIFX_PushAside, false )
    KTool.SetActive( self.ImgbgTips, true )
    ---
    self.playState = PlayState.Playing
    self.isSuccess = false
    self.playerTouchCount = 0

    if isNotNull(playTipsTxt_) then 
        CfUtils.FillText(self.playTipsTxt, playTipsTxt_)
    end

    --- 延时后再播放 抖动动画:
    IdolLive3D_Utils.StopCoroutine(self.co_1)
    self.co_1 = cs_coroutine.start(function()        
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.5 ))
        CfUtils.PlayAnimation( self.Interaction.gameObject, animName_Battle, false )
    end)
end



---@param retTable table @ 返回值容器, retTable.isSuccess 装入 "玩家是否获胜"
function IdolLive3D_UIQTE:EndPlay( retTable )
    self.playState = PlayState.Finished
    --self:_Show(false)
    retTable.isSuccess = (self.isSuccess == true)

    CfUtils.PlayAnimation( self.Interaction.gameObject, (self.isSuccess == true) and animName_PlayerWin or animName_RoleWin, false )

    --- 等动画播完后 关闭 qte ui
    IdolLive3D_Utils.StopCoroutine(self.co_1)
    self.co_1 = cs_coroutine.start(function()        
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 1 ))
        self:_Show(false)
    end)
end






return IdolLive3D_UIQTE
